/**
 * Helper: get unique country names from the dataset.
 */
export function getCountries() {
  return [...new Set(data.map((d) => d.country))];
}

/**
 * Helper: get data for a single country.
 */
export function getCountryData(country) {
  return data.filter((d) => d.country === country);
}

/**
 * Helper: get the year range in the dataset.
 */
export function getYearRange() {
  const years = data.map((d) => d.year);
  return [Math.min(...years), Math.max(...years)];
}
